function showAccess(){
 const overlay=document.createElement('div');overlay.className='project-library-shade';overlay.id='accessDialog';
 overlay.innerHTML='<form class="flow-card glass"><div class="micro">PRE—DESIGN / WORKSPACE</div><h2>连接项目空间</h2><p class="flow-desc">输入管理员提供的访问令牌。</p><label class="field-label" for="accessToken">访问令牌</label><input id="accessToken" class="field-input" type="password" autocomplete="off" required/><div class="flow-actions"><span></span><button class="primary-btn" type="submit">进入项目空间 ↗</button></div></form>';
 document.body.append(overlay);overlay.querySelector('form').onsubmit=async event=>{event.preventDefault();server.token=$('#accessToken').value.trim();try{await refreshProjects();sessionStorage.setItem('pre-access',server.token);overlay.remove()}catch(error){toast(error.message)}};
}
function addFiles(input){const files=Array.from(input||[]);for(const file of files){if(file.size>10*1024*1024){toast('单份资料不能超过 10 MB');continue}if(!/\.(pdf|txt|md|csv|json|png|jpe?g|webp)$/i.test(file.name)){toast('当前支持 PDF、文本资料及 PNG、JPEG、WebP 图片');continue}if(!state.files.some(f=>f.name===file.name&&f.size===file.size))state.files.push({name:file.name,size:file.size,type:file.type,file})}renderFiles()}
async function uploadFiles(projectId,files,active=()=>true){const revision=server.current?.revision??0;for(const item of files){if(!active())return;if(!item.file)continue;const content=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(String(r.result).split(',')[1]);r.onerror=reject;r.readAsDataURL(item.file)});if(!active())return;item.requestId??=requestId();await api(`/projects/${projectId}/materials`,{requestId:item.requestId,baseRevision:revision,filename:item.name,content})}}
async function startProcessing(){
 if(state.processing)return;const generation=++server.navigation;const files=[...state.files];const name=state.projectName;const metadata={type:state.projectType,location:state.projectLocation,regionDetail:state.projectRegionDetail,brief:$('#projectBrief').value};const active=()=>generation===server.navigation;state.processing=true;setStage('processing');$('#entryContent').classList.add('hidden');$('#processContent').classList.remove('hidden');$('#processList').innerHTML='';
 try{const body={name,metadata};const fingerprint=JSON.stringify(body);if(server.createRequest?.fingerprint!==fingerprint)server.createRequest={fingerprint,id:requestId()};
 $('#processMeta').textContent='正在建立服务器项目空间';$('#progressFill').style.width='15%';const project=await api('/projects',{...body,requestId:server.createRequest.id});if(!active())return;state.currentProjectId=project.id;const initial=await api(`/projects/${project.id}/state`);if(!active())return;server.current=initial;
 $('#processMeta').textContent='正在上传原件并核验内容哈希';await uploadFiles(project.id,files,active);if(!active())return;$('#progressFill').style.width='65%';
 $('#progressFill').style.width='100%';$('#processMeta').textContent='资料已登记，请选择需要执行的研究范围';server.createRequest=null;await refreshProjects();if(!active())return;await refreshCurrent();if(!active())return;state.processing=false;enterWorkspace({resume:true,snapshot:{}});watchProject(project.id);void globalThis.prePlatform?.openResearch();
 }catch(error){if(!active())return;state.processing=false;setStage('create');$('#entryContent').classList.remove('hidden');$('#processContent').classList.add('hidden');toast(error.message)}
}
function startConsult(){setStage('consult');$('#consultComposer').classList.remove('hidden');$('#confirmOutline').classList.remove('hidden');$('#confirmOutline').textContent='进入项目工作台 ↗';$('.consult-help').textContent='实际提案在工作台审阅确认，进入工作台不会自动批准。';renderConsult()}
function renderConsult(){if(!server.current)return;$('#consultStream').innerHTML='';for(const job of server.current.jobs){if(job.result?.response)consultBubble(escapeHTML(job.result.response).replaceAll('\n','<br>'));else if(job.error)consultBubble(escapeHTML(job.error));else consultBubble(statusText[job.status]||job.status)}scrollConsult()}
function consultAnswer(answer){void safely(async()=>{await mutate('chat',{text:answer});$('#consultInput').value='';renderConsult()})}
function finishConsult(){startConsult()}
function askQuestion(){}
async function openExistingProject(id){if(server.loading)return;const generation=++server.navigation;await safely(async()=>{closeProjectMenu();closeLibrary();$('#resumeProjectName').textContent=projectRecords.find(p=>p.id===id)?.name||'项目';$('#resumeDescription').textContent='正在读取服务器保存的资料、专业状态、批注与会话。';setStage('resume');state.currentProjectId=id;state.selected=null;state.activeScript=null;state.activeArt=null;$('#previewOverlay').classList.add('hidden');await refreshCurrent(true);if(generation!==server.navigation||state.currentProjectId!==id||state.stage!=='resume')return;enterWorkspace({resume:true,snapshot:{}});watchProject(id)})}
function applySnapshot(value){
 server.current=value;state.projectName=value.name;state.projectType=value.type||'其他类型';state.projectLocation=value.location||'';state.files=value.materials.map(f=>({name:f.filename,size:f.bytes}));
 state.annotations=value.annotations.map(n=>({...n,targetId:n.reference?.id||n.anchor,targetKind:n.reference?.kind||'script',targetTitle:n.reference?.title||n.anchor,excerpt:n.reference?.excerpt||'',createdAt:n.created_at?new Date(n.created_at).toLocaleString('zh-CN'):'',status:n.status==='completed'?'done':n.status,batchId:n.batch_id}));
 state.scripts={};const ids=new Set((value.core.stateObjects||[]).map(o=>o.objectId));for(const p of value.core.proposals||[])if(p.status==='pending_review')ids.add(p.envelope.target_object_id);if(!ids.size)ids.add('PS01');
 [...ids].sort().forEach((objectId,index)=>{const id=`script-${Math.floor(index/2)+1}-${index%2+1}`,confirmed=(value.core.stateObjects||[]).find(o=>o.objectId===objectId),proposal=[...(value.core.proposals||[])].reverse().find(p=>p.status==='pending_review'&&p.envelope.target_object_id===objectId);const payload=proposal?.envelope.change_set?.payload||confirmed?.value;
 state.scripts[id]={id,objectId,proposalId:proposal?.proposalId,body:payload?textValue(payload.data??payload):'等待资料分析与专业提案。',payload,confirmed:confirmed?.value,thesis:payload?.data?.start_reason||payload?.data?.canonical_name||'等待专业分析',evidence:payload?.quality?.issues?.length?textValue(payload.quality.issues):'内容来自项目资料与 Agent 提案；尚无已记录的缺项，不代表已经核验。',visualBrief:'当前为专业状态的文字成果页；完整图文编排尚未接入。',approved:!!confirmed&&!proposal,generated:!!confirmed,revision:value.revision};});
 $('#sidebarProjectName').textContent=value.name;updateProjectSwitcher();globalThis.prePlatform?.onState(value);
}
async function refreshCurrent(force=false){const id=state.currentProjectId;if(!id)return;const value=await api(`/projects/${id}/state`);if(state.currentProjectId!==id)return;const fingerprint=JSON.stringify(value);if(!force&&server.current?.id===id&&server.fingerprints.get(id)===fingerprint)return;server.fingerprints.set(id,fingerprint);applySnapshot(value);if(state.stage==='workspace'){renderGraph();initChat();updateAnnotationUI();if(state.activeScript&&!$('#previewOverlay').classList.contains('hidden'))renderScriptPage()}if(state.stage==='consult')renderConsult();updatePipelineUI()}
function watchProject(id){server.watch?.abort();const abort=new AbortController();server.watch=abort;void(async()=>{let cursor='0';while(!abort.signal.aborted&&state.currentProjectId===id){try{const response=await fetch(`/api/projects/${id}/events?after=${cursor}`,{headers:{Authorization:'Bearer '+server.token},signal:abort.signal});if(!response.ok)throw new Error('状态连接中断');const reader=response.body.getReader(),decoder=new TextDecoder();let buffer='';while(!abort.signal.aborted){const chunk=await reader.read();if(chunk.done)break;buffer+=decoder.decode(chunk.value,{stream:true});let at;while((at=buffer.indexOf('\n\n'))>=0){const block=buffer.slice(0,at);buffer=buffer.slice(at+2);const next=/^id: (\d+)/m.exec(block)?.[1];if(next){cursor=next;await refreshCurrent()}}}}catch(error){if(abort.signal.aborted)return}await new Promise(r=>setTimeout(r,1500))}})()}
function buildData(){const scripts=Object.values(state.scripts),chapters=[];for(let i=0;i<scripts.length;i++){const r=scripts[i],c=Math.floor(i/2),j=i%2;if(!chapters[c])chapters[c]={id:`chapter-${c+1}`,index:c+1,name:c===0?'项目背景':'专业研究',sections:[]};chapters[c].sections.push({id:`section-${c+1}-${j+1}`,name:r.objectId==='PS01'?'项目基本情况与启动原因':r.objectId,number:`${c+1}.${j+1}`,script:{id:r.id},artifact:{id:`page-${c+1}-${j+1}`,title:r.objectId==='PS01'?'项目基本情况':r.objectId,type:'HTML',visual:'text',chapter:c+1,section:j+1,sourceSection:r.objectId,pageCount:1,generated:r.generated,record:r}})}return chapters}
function scriptStats(){const rows=Object.values(state.scripts);return{total:rows.length,approved:rows.filter(r=>r.approved).length,generated:rows.filter(r=>r.generated).length,pages:rows.filter(r=>r.generated).length}}
function updatePipelineUI(){if(typeof state==='undefined')return;const st=scriptStats(),pending=Object.values(state.scripts).filter(r=>r.proposalId),running=server.current?.jobs.some(j=>['queued','running'].includes(j.status));$('#scriptProgress').textContent=`文字成果 ${st.approved}/${st.total} 已确认`;const btn=$('#pipelineBtn');btn.textContent=running?'正在执行任务…':pending.length?`审阅 ${pending.length} 项待确认提案`:'等待专业提案';btn.disabled=!!running||!pending.length||server.loading;$('#chatSubmit').disabled=!!running;$('#consultSend').disabled=!!running}
function scriptStatusLabel(rec){return rec.proposalId?'待确认':rec.approved?'已确认':'待分析'}
function initChat(){$('#chatHistory').innerHTML='<div class="chat-date">项目会话 · 服务器记录</div>';for(const job of server.current?.jobs||[]){if(job.user_text)addChat('me',job.user_text,false);if(job.result?.response)addChat('ai',escapeHTML(job.result.response).replaceAll('\n','<br>'));else if(job.error)addChat('system',escapeHTML(job.error));else addChat('system',escapeHTML(statusText[job.status]||job.status))}}
function handleChatSubmit(){const text=$('#chatInput').value.trim();if(!text)return;void safely(async()=>{if(state.selected){const rec=recordForReference(state.selected.id);if(!rec)throw new Error('请选择具体章节、文字脚本或成果再批注');if(server.editingNote){await mutate(`annotations/${server.editingNote}/edit`,{text});server.editingNote=null}else await mutate('annotations',{anchor:rec.objectId,text,reference:{...state.selected}});clearReference();toast('批注已保存，尚未执行 Agent')}else await mutate('chat',{text});$('#chatInput').value='';})}
function recordForReference(id){const base=String(id).split('#')[0];return Object.values(state.scripts).find(r=>r.objectId===base||r.id===base||base.replace(/^page-/,'script-').split('__page__')[0]===r.id||base.replace(/^section-/,'script-')===r.id)}
function updateAnnotationUI(){const pending=state.annotations.filter(a=>['pending','failed','interrupted'].includes(a.status)).length;$('#annotationCount').textContent=pending;$('#annotationSummary').textContent='条批注待统一提交';if($('#historyCount'))$('#historyCount').textContent=state.annotations.length-pending;renderAnnotationList()}
function setAnnotationView(view){annotationDrawerView=view==='history'?'history':'pending';const history=annotationDrawerView==='history';$('#drawerHeading').textContent=history?'历史批注':'批注箱';$('#drawerDescription').textContent=history?'已提交批注及实际处理状态':'先集中记录，最后统一交给 Agent 修改';$('#annotationHistoryBtn').textContent=history?'← 返回待提交':'历史批注';$('#pendingDrawerFooter').classList.toggle('hidden',history);$('#historyDrawerFooter').classList.toggle('hidden',!history);renderAnnotationList()}
function renderAnnotationList(){const pending=a=>['pending','failed','interrupted'].includes(a.status),history=annotationDrawerView==='history',rows=state.annotations.filter(a=>history?!pending(a):pending(a));$('#annotationList').innerHTML=rows.map(a=>`<div class="annotation-item"><div class="annotation-item-top"><span class="anno-status ${a.status==='done'?'done':''}">${escapeHTML(a.status==='done'?'已完成':statusText[a.status]||a.status)}</span><strong>${escapeHTML(a.targetTitle)}</strong></div><p>${escapeHTML(a.text)}</p><div class="anno-tools"><span class="scope">版本 ${a.base_revision} · ${escapeHTML(a.createdAt)}</span>${!history?`<div><button data-server-edit="${a.id}">编辑</button><button data-server-delete="${a.id}">删除</button></div>`:""}</div></div>`).join('')||'<div class="drawer-empty"><b>暂无记录</b><p>选择具体内容并添加批注。</p></div>';$('#batchSubmitBtn').disabled=!state.annotations.some(pending)||server.current?.jobs.some(j=>['queued','running'].includes(j.status));$('#batchSubmitBtn').textContent='统一提交给 Agent ↗'}
function textValue(value){const labels={canonical_name:'项目名称',aliases:'其他名称',location:'项目地点',name:'名称',object_type:'项目类型',origin_mode:'启动方式',trigger_events:'启动事件',start_reason:'启动原因',time_constraints:'时间约束',evidence_refs:'资料依据',status:'状态',issues:'待核验事项',date:'日期',event_type:'事件类型',admin_codes:'行政区划代码',geometry_refs:'空间资料',project_id:'项目编号',event_id:'事件编号',claim_class:'信息性质',locator:'原文位置',evidence_id:'资料引用',asset_id:'原件编号',version_id:'原件版本'};if(value===null||value===undefined)return'待补充';if(Array.isArray(value))return value.length?value.map(textValue).join('\n'):'未提供';if(typeof value==='object')return Object.entries(value).map(([k,v])=>`${labels[k]||k}：${textValue(v)}`).join('\n\n');return String(value)}
function renderScriptPage(){const sec=state.activeScript;if(!sec)return;const rec=state.scripts[sec.script.id];if(!rec)return;$('#previewTitle').textContent=`文字脚本 · ${sec.name} · R${rec.revision}`;$('#scriptReviewActions').classList.remove('hidden');$('#scriptEditBtn').textContent='添加修改意见';$('#scriptApproveBtn').textContent=rec.proposalId?'确认本节提案':rec.approved?'已确认 ✓':'等待提案';$('#scriptApproveBtn').disabled=!rec.proposalId||server.loading;$('#previewQuoteBtn').textContent='引用本节';$('#previewQuoteBtn').onclick=()=>setReference({id:rec.id,kind:'script',title:sec.name,excerpt:rec.thesis});updatePreviewNav();const w=$('#previewSheet');w.className='preview-sheet script-sheet';w.style.width='';w.innerHTML=`<div class="script-doc-top"><div class="micro">PRE—DESIGN · CONTENT SCRIPT</div><div class="script-doc-state">${scriptStatusLabel(rec)}</div></div><div class="script-doc-scroll"><div class="script-doc-main"><div class="script-meta">第 ${sec.number} 节 · R${rec.revision}</div><h2>${escapeHTML(sec.name)}</h2><div class="script-main-thesis">${escapeHTML(rec.thesis)}</div><div class="script-divider"><span>具体策划文字</span><span>可选中添加批注</span></div><div class="script-paragraphs">${rec.body.split(/\n\s*\n/).map((p,i)=>`<p class="selectable" data-block="paragraph-${i+1}">${escapeHTML(p).replaceAll('\n','<br>')}</p>`).join('')}</div></div><aside class="script-doc-aside"><div class="script-aside-card"><span>研究依据 / 缺失项</span><p>${escapeHTML(rec.evidence)}</p></div><div class="script-aside-card"><span>成果状态</span><p>${escapeHTML(rec.visualBrief)}</p></div></aside></div>`;w.querySelectorAll('.selectable').forEach(el=>el.onclick=()=>{if(window.getSelection()?.toString().trim())return;const r=el.getBoundingClientRect();showPreviewAction({id:rec.id+'#'+el.dataset.block,kind:'block',title:sec.name,excerpt:el.textContent.slice(0,700)},r.right,r.top)})}
function renderMini(art){return `<div class="art-mini"><div class="mini-left"><div class="mini-head"></div><div class="mini-title">${escapeHTML(art.title)}</div><div class="mini-line"></div><div class="mini-line short"></div><div class="mini-line"></div></div></div>`}
function renderPreviewPage(){const entry=currentVisualEntry();if(!entry)return;const art=entry.art,rec=art.record;previewData=art;state.activeArt=art;$('#scriptReviewActions').classList.add('hidden');$('#previewTitle').textContent=`${art.title} · 已确认版本 ${rec.revision}`;$('#previewQuoteBtn').textContent='引用本页';$('#previewQuoteBtn').onclick=()=>setReference({id:rec.id,kind:'page',title:art.title,excerpt:rec.thesis});updatePreviewNav();const w=$('#previewSheet');w.className='preview-sheet script-sheet';w.style.width='';w.innerHTML=`<div class="script-doc-top"><div class="micro">PRE—DESIGN · PROJECT RECORD</div><div class="script-doc-state">已确认文字成果</div></div><div class="script-doc-scroll"><div class="script-doc-main"><h2>${escapeHTML(art.title)}</h2><div class="script-paragraphs"><p class="selectable">${escapeHTML(textValue(rec.confirmed?.data??rec.confirmed)).replaceAll('\n','<br>')}</p></div></div></div>`}
